namespace {
const QString path=QStringLiteral("/home/we6jbo/Projects/AncesTaleextended/missing_family_records.json");
const QStringList fields={"birth_date","birth_location","death_date","death_location","mother_name","father_name"};
QStringList missing(const QJsonObject& p){QStringList m;for(const auto& f:fields)if(p.value(f).toString().trimmed().isEmpty())m<<f;return m;}
bool pending(const QJsonObject& p){return p.value("research_status").toString()!="resolved" || p.value("resolution_notes").toString().trimmed().isEmpty();}
bool parse(const QByteArray& bytes,QJsonObject& result){QJsonParseError err;auto d=QJsonDocument::fromJson(bytes,&err);if(err.error!=QJsonParseError::NoError||!d.isObject()||!d.object().value("people").isArray())return false;for(const auto& v:d.object().value("people").toArray())if(!v.isObject()||v.toObject().value("name").toString().trimmed().isEmpty())return false;result=d.object();return true;}
QString promptRules(){return QStringLiteral("Use the private shared JSON at /home/we6jbo/Projects/AncesTaleextended/missing_family_records.json. Read /home/we6jbo/Projects/AncesTale/workflow/CONTINUED-RESEARCH.md. Research selected people, cite evidence, add newly identified relatives, preserve existing verified information and unknown nulls. Never invent identities or publish the JSON. Use a coordinated lock, private backup, validation and atomic replacement. Do not modify signed artifacts.\nSelected records:\n");}
}
ContinuedResearchPanel::ContinuedResearchPanel(QWidget* parent):QWidget(parent){
 auto* layout=new QVBoxLayout(this); layout->addWidget(new QLabel("Private shared research queue — checked means continued research required",this));
 auto* bar=new QHBoxLayout;search=new QLineEdit(this);search->setPlaceholderText("Search names or TG identifiers");filter=new QComboBox(this);filter->addItems({"All","Still missing","Resolved"});bar->addWidget(search,1);bar->addWidget(filter);layout->addLayout(bar);
 status=new QLabel(this);status->setWordWrap(true);layout->addWidget(status);
 table=new QTableWidget(0,4,this);table->setHorizontalHeaderLabels({"Missing","Person","Missing fields","Last researched"});table->setSelectionBehavior(QAbstractItemView::SelectRows);table->setSelectionMode(QAbstractItemView::ExtendedSelection);table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->horizontalHeader()->setSectionResizeMode(0,QHeaderView::ResizeToContents);table->horizontalHeader()->setSectionResizeMode(1,QHeaderView::ResizeToContents);table->horizontalHeader()->setSectionResizeMode(2,QHeaderView::Stretch);layout->addWidget(table,3);
 detail=new QPlainTextEdit(this);detail->setReadOnly(true);detail->setPlaceholderText("Select a person to view private research evidence and family links.");layout->addWidget(detail,2);
 auto* buttons=new QHBoxLayout;auto add=[&](const QString& label,auto fn){auto* b=new QPushButton(label,this);buttons->addWidget(b);connect(b,&QPushButton::clicked,this,fn);};
 add("Refresh JSON",[this]{refresh(true);});add("Add person",[this]{addPerson();});add("Copy Vibe prompt",[this]{copyPrompt();});add("Resolve with evidence",[this]{resolve(true);});add("Reopen",[this]{resolve(false);});layout->addLayout(buttons);
 connect(search,&QLineEdit::textChanged,this,[this]{render();});connect(filter,&QComboBox::currentIndexChanged,this,[this]{render();});connect(table,&QTableWidget::itemSelectionChanged,this,[this]{auto ids=selected();if(ids.size()==1)detail->setPlainText(QString::fromUtf8(QJsonDocument(data.value("people").toArray().at(ids.first()).toObject()).toJson(QJsonDocument::Indented)));else detail->clear();});
 auto* timer=new QTimer(this);connect(timer,&QTimer::timeout,this,[this]{refresh();});timer->start(1000);refresh(true);
}
QList<int> ContinuedResearchPanel::selected() const{QList<int> ids;for(auto idx:table->selectionModel()->selectedRows())if(auto* item=table->item(idx.row(),0))ids<<item->data(Qt::UserRole).toInt();return ids;}
void ContinuedResearchPanel::refresh(bool force){QFile f(path);QJsonObject next;if(!f.open(QIODevice::ReadOnly)){valid=false;status->setText("Cannot read shared JSON; last valid view retained. Install the JSON at: "+path);return;}auto bytes=f.readAll();if(!force&&valid&&bytes==snapshot)return;if(!parse(bytes,next)){valid=false;status->setText("Invalid research JSON; last valid view retained. No changes saved.");return;}data=next;snapshot=bytes;valid=true;render();}
void ContinuedResearchPanel::render(){if(!valid)return;auto people=data.value("people").toArray();int count=0;table->setRowCount(0);for(int i=0;i<people.size();++i){auto p=people.at(i).toObject();bool needs=pending(p);if(needs)++count;auto name=p.value("name").toString();QStringList ids;for(auto v:p.value("identifiers").toArray())ids<<v.toString();if(!(name+" "+ids.join(" ")).contains(search->text(),Qt::CaseInsensitive)||(filter->currentIndex()==1&&!needs)||(filter->currentIndex()==2&&needs))continue;int row=table->rowCount();table->insertRow(row);auto* ck=new QTableWidgetItem;ck->setFlags(Qt::ItemIsEnabled|Qt::ItemIsSelectable);ck->setCheckState(needs?Qt::Checked:Qt::Unchecked);ck->setData(Qt::UserRole,i);table->setItem(row,0,ck);table->setItem(row,1,new QTableWidgetItem(name));auto m=missing(p);table->setItem(row,2,new QTableWidgetItem(m.isEmpty()?"None recorded":m.join(", ")));table->setItem(row,3,new QTableWidgetItem(p.value("last_researched").toString()));}status->setText(QString("%1 people | %2 still requiring research | %3 resolved | %4 separate hypotheses | %5 shown").arg(people.size()).arg(count).arg(people.size()-count).arg(data.value("possible_missing_generations").toArray().size()).arg(table->rowCount()));}
void ContinuedResearchPanel::copyPrompt(){if(!valid)return;QJsonArray chosen;auto people=data.value("people").toArray();auto ids=selected();for(int i=0;i<people.size();++i){auto p=people.at(i).toObject();if(ids.contains(i)||(ids.isEmpty()&&pending(p))){QJsonObject q;for(const QString& k:QStringList{"name","identifiers","research_id","database_record_id","geography_serial"})if(p.contains(k))q.insert(k,p.value(k));chosen.append(q);}}QApplication::clipboard()->setText(promptRules()+QString::fromUtf8(QJsonDocument(chosen).toJson()));status->setText(QString("Copied private Vibe prompt for %1 people.").arg(chosen.size()));}
bool ContinuedResearchPanel::save(const QJsonObject& next){auto fail=[this](const QString& s){QMessageBox::warning(this,"Research not saved",s);return false;};if(!valid||QFileInfo(path).isSymLink())return fail("Shared file unavailable or unsafe.");QLockFile lock(path+".lock");if(!lock.tryLock(0))return fail("Another coordinated writer is active; retry later.");QFile original(path);if(!original.open(QIODevice::ReadOnly)||original.readAll()!=snapshot)return fail("File changed. Refresh and retry your decision.");original.close();QString dir=QFileInfo(path).absolutePath()+"/.research-backups";if(QFileInfo(dir).isSymLink()||!QDir().mkpath(dir)||!QFile::setPermissions(dir,QFileDevice::ReadOwner|QFileDevice::WriteOwner|QFileDevice::ExeOwner))return fail("Cannot secure backup directory.");QString backup=dir+"/missing_family_records-"+QUuid::createUuid().toString(QUuid::WithoutBraces)+".json";auto write=[](const QString& name,const QByteArray& bytes){QSaveFile f(name);f.setDirectWriteFallback(false);return f.open(QIODevice::WriteOnly)&&f.setPermissions(QFileDevice::ReadOwner|QFileDevice::WriteOwner)&&f.write(bytes)==bytes.size()&&f.commit();};if(!write(backup,snapshot))return fail("Private backup failed.");auto bytes=QJsonDocument(next).toJson();QJsonObject checked;if(!parse(bytes,checked))return fail("Validation failed.");if(!original.open(QIODevice::ReadOnly)||original.readAll()!=snapshot)return fail("Concurrent update detected; refresh and retry.");original.close();if(!write(path,bytes))return fail("Atomic replacement failed; backup retained.");refresh(true);return true;}
void ContinuedResearchPanel::addPerson(){if(!valid)return;auto before=snapshot;bool ok=false;auto name=QInputDialog::getText(this,"Add person","Full name (unverified):",QLineEdit::Normal,{},&ok).trimmed();if(!ok||name.isEmpty()||before!=snapshot)return;auto people=data.value("people").toArray();for(auto v:people)if(v.toObject().value("name").toString().compare(name,Qt::CaseInsensitive)==0){QMessageBox::information(this,"Review identity","Matching name exists; review before adding another identity.");return;}QJsonObject p{{"name",name},{"research_id",QUuid::createUuid().toString(QUuid::WithoutBraces)},{"research_status","pending"},{"identifiers",QJsonArray{}},{"spouse_names",QJsonArray{}},{"children",QJsonArray{}},{"research_notes",QJsonArray{QStringLiteral("Manually added; unverified")}}};for(auto f:fields)p.insert(f,QJsonValue(QJsonValue::Null));p.insert("missing_fields",QJsonArray::fromStringList(fields));people.append(p);auto next=data;next.insert("people",people);auto counts=next.value("counts").toObject();counts.insert("output_people",int(people.size()));next.insert("counts",counts);save(next);}
void ContinuedResearchPanel::resolve(bool resolved){if(!valid)return;auto ids=selected();if(ids.size()!=1){QMessageBox::information(this,"Research decision","Select one person.");return;}auto people=data.value("people").toArray();int i=ids.first();auto p=people.at(i).toObject();auto before=snapshot;bool ok=false;auto note=QInputDialog::getMultiLineText(this,resolved?"Resolve with evidence":"Reopen research",resolved?"Cite source and explain why research is complete, including unknown fields:":"Reason for reopening:",{},&ok).trimmed();if(!ok||note.isEmpty())return;if(before!=snapshot){QMessageBox::warning(this,"Research changed","Refresh and choose the record again.");return;}QJsonObject event{{"status",resolved?"resolved":"pending"},{"note",note},{"at",QDateTime::currentDateTimeUtc().toString(Qt::ISODate)}};auto history=p.value("research_decisions").toArray();history.append(event);p.insert("research_decisions",history);p.insert("research_status",resolved?"resolved":"pending");if(resolved)p.insert("resolution_notes",note);p.insert("last_researched",QDate::currentDate().toString(Qt::ISODate));people.replace(i,p);auto next=data;next.insert("people",people);save(next);}
